  goals: [5, 1, 12, 1, 'goals'],
  people: [0, 0, 12, 1, 'people'],
  stepout: [0, 0, 6, 1, 'people who wait for the robot'],
  beacons: [0, 0, 60, 1, 'beacons (0: one per 32 m²)']
