  const r = S.robot;
  if (hyp(r.x - p.tr.p[0], r.y - p.tr.p[1]) >= p.tr.r) return false;
  p.go = true;
  logE(`A person steps out at (${p.x.toFixed(1)}, ${p.y.toFixed(1)})`);
